let type = msg.payload.type;
let count = flow.get("countMac");

if (msg.column == "button-1"){
    for (let index = 0; index < count; index++) {
        let saved_type = flow.get("ncdSensor")[index][1];
        if (type == saved_type) {
            let data = flow.get("ncdSensor")[index][7];
            msg.payload = data;
            if (msg.payload == undefined) {
                msg.payload = "";
            }
            return [msg, null];
        }
    }
}
if (msg.column == "button-2"){
    return [null, msg];
}

let length = msg.payload.length || 0;
if (msg.payload.length === 0)
{ 
    flow.set('countMac', undefined);
    flow.set('ncdSensor', undefined);
    return msg;
}
else{
    const mac = 0;
    let count = flow.get("countMac") || 0;
    let sensorType;
    let mode;
    let rssi;
    let newMac;
    let battery;
    let counter;
    let sensor_data;
    let flag = true;
    const dates = new Date();
    const formattedDate = dates.toLocaleString(); 
    const date = formattedDate;

    if(msg.payload.hasOwnProperty('mac')){
        newMac = msg.payload.mac;
        mode = msg.payload.mode;
        sensorType = msg.payload.type;
        rssi = msg.payload.rssi;
    }
    else {
        newMac = msg.payload.addr;
        mode = msg.topic;
        sensorType = msg.payload.sensor_type;
        rssi = msg.payload.rssi;
        battery = msg.payload.battery_percent;
        counter = msg.payload.counter;
        sensor_data = msg.payload.sensor_data;
    }
    for (let index = 0; index < count; index++) {
        let oldMac = flow.get("ncdSensor["+index+"]")[mac] || 0; 
        if (oldMac == newMac) 
        {
            flow.set("ncdSensor[" + index + "]", [newMac, sensorType, mode, battery, rssi, date, counter, sensor_data]); 
            flag = false;
        }
    }
    if(flag){
        flow.set("ncdSensor[" + count + "]", [newMac, sensorType, mode, battery, rssi, date, counter, sensor_data]); 
        count++;
        flow.set("countMac", count);
    }
    let inputArray = flow.get("ncdSensor") || 0;
    const outputArray = inputArray.map(item => {
        return {
            "button-1": "Inspect",
            "button-2": "Last Transmissions",
            "mac": item[0],
            "type": item[1],
            "mode": item[2],
            "battery_p": item[3] == undefined? "-" : item[3] + "%",
            "rssi": item[4] + " %",
            "date": item[5],
            "count": item[6] == undefined? "-" : item[6]
        };
    });
    msg = {};
    msg.payload = outputArray;
    return msg;
}

if(msg.topic != "modem_mac"){
    if (msg.payload.hasOwnProperty('mac')) {
        const date = new Date();
        msg.payload.addr = msg.payload.mac;
        msg.payload.received = date.toLocaleString(); 
        msg.payload.counter = "-";
        msg.topic = msg.payload.mode;

    }
    let flag = true;
    let count = flow.get("countMac") || 0;
    let newMac = msg.payload.addr;
    for (let index = 0; index < count; index++) {
        let storedData = flow.get("sensorData[" + index + "]") || {
            address: msg.payload.addr,
            counter: [],
            type: [],
            rssi: [],
            date: []
        };

        if (storedData.address == newMac) { 
            // Convert the received timestamp to a readable format
            const date = new Date(msg.payload.received);
            const formattedDate = date.toLocaleString(); 

            // Add the new data to the arrays
            storedData.counter.push(msg.payload.counter);
            storedData.type.push(msg.topic);
            storedData.rssi.push(msg.payload.rssi);
            storedData.date.push(formattedDate);

            // Limit the stored data to the last 10 entries
            if (storedData.counter.length > 10) {
                storedData.counter.shift();
                storedData.type.shift();
                storedData.rssi.shift();
                storedData.date.shift();
            }

            // Update the flow variable
            flow.set("sensorData[" + index + "]", storedData);

            flag = false;
        }
    }
    if (flag) {
        let msg1 = {};
        msg1.payload = "nuevo";
        node.send(msg1);
        let storedData = {
            address: msg.payload.addr,
            counter: [],
            type: [],
            rssi: [],
            date: []
        };
        // Convert the received timestamp to a readable format
        const date = new Date(msg.payload.received);
        const formattedDate = date.toLocaleString(); // Change format as needed

        // Add the new data to the arrays
        storedData.counter.push(msg.payload.counter);
        storedData.type.push(msg.topic);
        storedData.rssi.push(msg.payload.rssi);
        storedData.date.push(formattedDate);

        // Limit the stored data to the last 10 entries
        if (storedData.counter.length > 10) {
            storedData.counter.shift();
            storedData.type.shift();
            storedData.rssi.shift();
            storedData.date.shift();
        }

        // Update the flow variable
        flow.set("sensorData[" + count + "]", storedData);
        count++;
        flow.set("countMac", count);
    }
}

let count = flow.get("countMac") || 0;
let address = msg.payload.mac;
for (let index = 0; index < count; index++) {
    let storedData = flow.get("sensorData[" + index + "]") || {
        address: msg.payload.addr,
        counter: [],
        type: [],
        rssi: [],
        date: []
    };
    if (storedData.address == address) {
        msg.stored = storedData;
        return msg;
    }
}

if (msg.topic != "modem_mac") 
{
    let percent = ((msg.payload.rssi - 90) * (100 - 0) / (40 - 90) + 0);
    msg.payload.rssi = percent;
    return msg;
}

let sensorData = msg.payload;
var formattedJson = JSON.stringify(sensorData, null, 4);
msg.payload = formattedJson;
